using System;
using System.Collections.Generic;
using System.Threading;

// 레이드 정산 장부. 전투 로그를 처리하는 워커 스레드 여러 개가 동시에 호출한다.
public sealed class LootLedger
{
    private int _totalGold;
    private bool _firstKillClaimed;
    private readonly List<int> _drops = new List<int>();

    public int TotalGold => _totalGold;
    public int DropCount => _drops.Count;

    public void AddGold(int amount)
    {
        _totalGold += amount;
    }

    public void AddDrop(int itemId)
    {
        _drops.Add(itemId);
    }

    // 최초 처치 보너스: 장부 하나당 단 한 번만 true 를 반환한다.
    public bool TryClaimFirstKill()
    {
        if (_firstKillClaimed) return false;
        _firstKillClaimed = true;
        return true;
    }

    // 지금까지 기록된 드롭의 복사본(기록된 순서).
    public int[] SnapshotDrops()
    {
        return _drops.ToArray();
    }
}

