using System;
using System.Collections.Generic;
using System.Threading;

// 레이드 정산 장부. 전투 로그를 처리하는 워커 스레드 여러 개가 동시에 호출한다.
public sealed class LootLedger
{
    private int _totalGold;          // Interlocked 로만 갱신한다
    private int _firstKillClaimed;   // 0 = 미수령, 1 = 수령 (CompareExchange 용으로 int)
    private readonly object _dropsLock = new object();
    private readonly List<int> _drops = new List<int>();   // _dropsLock 을 잡고만 접근한다

    public int TotalGold => Volatile.Read(ref _totalGold);

    public int DropCount
    {
        get { lock (_dropsLock) { return _drops.Count; } }
    }

    // 변수 하나에 대한 단일 연산: 락 없이 원자적 덧셈으로 충분하다.
    public void AddGold(int amount)
    {
        Interlocked.Add(ref _totalGold, amount);
    }

    // List<T> 는 내부 배열과 크기 등 여러 필드를 함께 바꾸므로 락으로 임계 구역을 만든다.
    public void AddDrop(int itemId)
    {
        lock (_dropsLock) { _drops.Add(itemId); }
    }

    // "확인 후 변경"을 한 번의 원자적 연산으로: 0 이었을 때만 1 로 바꾸고, 바꾼 스레드만 true.
    public bool TryClaimFirstKill()
    {
        return Interlocked.CompareExchange(ref _firstKillClaimed, 1, 0) == 0;
    }

    // 읽기도 같은 락으로 보호한다. 복사본을 돌려주므로 호출자는 락 밖에서 안전하게 순회한다.
    public int[] SnapshotDrops()
    {
        lock (_dropsLock) { return _drops.ToArray(); }
    }
}

