using System;
using System.Threading;

public sealed class Inventory
{
    public readonly int OwnerId;                 // 플레이어마다 고유
    public readonly object Gate = new object();  // 이 인벤토리를 보호하는 락
    private int _gold;

    public Inventory(int ownerId, int gold)
    {
        OwnerId = ownerId;
        _gold = gold;
    }

    public int Gold
    {
        get { return _gold; }
    }

    // Gate 를 잡은 스레드만 호출한다.
    public void ApplyDelta(int delta)
    {
        _gold += delta;
    }
}

public static class TradeService
{
    // from 의 골드 amount 를 to 로 옮기고 true 를 반환한다.
    // amount <= 0, from 과 to 가 같은 인벤토리, 잔액 부족이면 아무것도 바꾸지 않고 false.
    public static bool Transfer(Inventory from, Inventory to, int amount)
    {
        if (ReferenceEquals(from, to)) return false;
        if (from.Gold < amount) return false;

        lock (from.Gate)
        {
            lock (to.Gate)
            {
                from.ApplyDelta(-amount);
                to.ApplyDelta(amount);
            }
        }
        return true;
    }
}

